import{_ as a,o as i,c as e,a3 as n}from"./chunks/framework.D3kUw6rp.js";const t="/assets/1.Dp1RxvQs.png",l="/assets/%E5%AF%B9%E6%AF%94.Bg2SNnZb.png",u=JSON.parse('{"title":"软链接的使用","description":"","frontmatter":{},"headers":[],"relativePath":"work/cocos/symlink/index.md","filePath":"work/cocos/symlink/index.md"}'),p={name:"work/cocos/symlink/index.md"};function o(h,s,r,d,c,k){return i(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="软链接的使用" tabindex="-1">软链接的使用 <a class="header-anchor" href="#软链接的使用" aria-label="Permalink to &quot;软链接的使用&quot;">​</a></h1><p>软链接可以创建文件的引用路径，让一个文件拥有多个访问路径。像章鱼的多个触脚，每个触脚都可以直达章鱼的真身。</p><h2 id="使用场景" tabindex="-1">使用场景 <a class="header-anchor" href="#使用场景" aria-label="Permalink to &quot;使用场景&quot;">​</a></h2><p>我们的编辑器在启动的时候会根据当前模式（正常｜开发）去不同的路径获取配置文件，扫描全局插件等。而此时如果你在开发一个全局插件，在没有使用软链接的情况下，你只能在每个环境的文件夹下放置该全局插件。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/Users/alan/.CocosCreator_Develop/extensions/your-plugin</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/Users/alan/.CocosCreator/extensions/your-plugin</span></span></code></pre></div><p>这样不方便维护，你需要不断的复制同步代码。通过软链，你可以把 <code>your-plugin</code> 放置在你平时的开发文件夹。然后通过配置软链接让两个环境下的 extensions 文件夹都有 <code>your-plugin</code> 的引用。 <strong>需要使用绝对路径</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ln</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /Users/alan/cocos/auto-register</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /Users/alan/.CocosCreator_Develop/extensions/auto-register</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ln</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /Users/alan/cocos/auto-register</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /Users/alan/.CocosCreator/extensions/auto-register</span></span></code></pre></div><p>这样你可以正常的开发你的插件，而不同环境的配置路径都拥有访问该插件的软链接。非常方便。</p><h2 id="命令" tabindex="-1">命令 <a class="header-anchor" href="#命令" aria-label="Permalink to &quot;命令&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 创建</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ln</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 原文件路径</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 目标软链接路径</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 查看(查看当前目录下，哪些文件是软链接)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -li</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 删除</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 目标软链接路径</span></span></code></pre></div><p>软连接也可以当作源目录继续创建新的软连接</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>源目录 &lt;-- 软连接A &lt;-- 软连接B</span></span></code></pre></div><p>注意：如果 cd 到软连接的目录下执行 <code>pwd</code> 命令显示的是当前软连接所在的地址，如果想知道该软连接的源目录，需要执行 <code>pwd -P</code>。</p><p>如果 cd 到 <code>软连接B</code> 执行 <code>pwd -P</code> 也会溯源到 <code>源目录</code></p><h2 id="效果" tabindex="-1">效果 <a class="header-anchor" href="#效果" aria-label="Permalink to &quot;效果&quot;">​</a></h2><p><img src="`+t+'" alt="image"></p><h2 id="和硬连接的区别" tabindex="-1">和硬连接的区别 <a class="header-anchor" href="#和硬连接的区别" aria-label="Permalink to &quot;和硬连接的区别&quot;">​</a></h2><p><img src="'+l+'" alt=""></p><h3 id="硬连接" tabindex="-1">硬连接 <a class="header-anchor" href="#硬连接" aria-label="Permalink to &quot;硬连接&quot;">​</a></h3><ul><li>不能连接文件夹</li><li>删除源文件，文件还在，因为硬连接依然保存对磁盘数据的引用</li></ul><h3 id="软连接" tabindex="-1">软连接 <a class="header-anchor" href="#软连接" aria-label="Permalink to &quot;软连接&quot;">​</a></h3><ul><li>可以连接文件夹</li><li>删除源文件，软连接失效，不可用</li></ul>',22)])])}const F=a(p,[["render",o]]);export{u as __pageData,F as default};
